 if(hj){const brk=hj.brk.find(b=>PZ_AGORA>=pzMin(b[0])&&PZ_AGORA<pzMin(b[1]));return `<div class="alert ${brk?'warn':'ok'}"><div><b>${brk?'Plantão · em intervalo':'Você está em plantão'}</b> · hoje ${hj.ini}–${hj.fim} (${esc(PROF(me).n)}). Atendimentos deste período contam como plantão, não por atendimento. ${info('Modalidade do atendimento: SHIFT (coberto por plantão) ou PER_ATTENDANCE. Rascunho não define modalidade.')}</div></div>`}
